        // always((p1 ∧ p2) => eventually((q1 ∧ p2) ∨ q2))
        assert forall |i: nat| (p1.and(p2)).implies(eventually((q1.and(p2)).or(q2))).satisfied_by(#[trigger] ex.suffix(i)) by {
            let exi = ex.suffix(i);
            if p1.and(p2).satisfied_by(exi) {
