                assert(p1.satisfied_by(exi));
                assert(p2.satisfied_by(exi));

                // Get that eventually(q1) from the always lemma
                assert(p1.implies(eventually(q1)).satisfied_by(exi)) by {
                    always_unfold(ex, p1.implies(eventually(q1)));
