                    always_unfold(ex, p2.implies(always(p2).or(eventually(q2))));
                };
                implies_apply(exi, p2, always(p2).or(eventually(q2)));
                assert(always(p2).or(eventually(q2)).satisfied_by(exi));

                if eventually(q2).satisfied_by(exi) {
