                    assert((q1.and(p2)).satisfied_by(exi.suffix(q1_witness)));
                    assert(((q1.and(p2)).or(q2)).satisfied_by(exi.suffix(q1_witness)));
                    eventually_proved_by_witness(exi, (q1.and(p2)).or(q2), q1_witness);
                }
